SELECT * FROM (SELECT dept_name, CASE WHEN budget >= 4461000 THEN 'high' WHEN budget >= 711000 THEN 'mid' ELSE 'low' END budget_bucket, SUM(CASE WHEN location = 'London' THEN budget ELSE 0 END) london_budget, SORT_ARRAY(COLLECT_SET(dept_name)) dept_name_list FROM departments GROUP BY dept_name, CASE WHEN budget >= 4461000 THEN 'high' WHEN budget >= 711000 THEN 'mid' ELSE 'low' END) s WHERE london_budget >= 30;
